            <el-icon class="session-icon"><ChatDotRound /></el-icon>
            <span class="session-title">{{ s.title }}</span>
          </div>
        </div>
        <div class="session-group" v-if="yesterdaySessions.length">
          <div class="session-group-title">昨天</div>
          <div
            v-for="s in yesterdaySessions"
            :key="s.id"
            class="session-item"
            :class="{ active: s.id === currentSession }"
            @click="selectSession(s.id)"
          >
            <el-icon class="session-icon"><ChatDotRound /></el-icon>
            <span class="session-title">{{ s.title }}</span>
          </div>
        </div>
        <div class="session-group" v-if="earlierSessions.length">
          <div class="session-group-title">更早</div>
          <div
